
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_2d_prhg07_HO2D_2_zk():
    # Prepare the input
    inp = test_data["HO2D"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_2d_prhg07", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-8.862277822225438e-01, -8.862291702441015e-01, -8.862327837664780e-01, -8.862421158733622e-01, -8.862659003420649e-01, -8.863252039484623e-01, -8.864676888900190e-01, -8.867885381085643e-01, -8.874279613286526e-01, -8.883919563665551e-01, -8.886873713881651e-01, -8.836530281364321e-01, -8.595092942684835e-01, -7.919615395229171e-01, -6.599626599304117e-01, -4.804008580414327e-01, -3.201362888009087e-01, -2.176538337797317e-01, -1.557394325920108e-01, -1.148604769204970e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


